// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function testFuzz_property(uint256 val, address caller) public {
        vm.assume(caller != address(0) && caller != address(this));

        vm.prank(caller);
        vm.deal(caller, 0);
        c.SetMinSum(val);

        assertTrue(c.MinSum() == val);
    }
}
